define('taoQtiPrint/qtiPrintRenderer/renderers/choices/SimpleChoice.ChoiceInteraction',['tpl!taoQtiPrint/qtiPrintRenderer/tpl/choices/simpleChoice.choiceInteraction', 'taoQtiPrint/qtiPrintRenderer/helpers/container'], function (tpl, getContainer) {
  'use strict';
  function hasRelativeSizedImage($container) {
    var flag = false;
    var $img = $container.find('img');
    if ($img && $img.length && $img.attr('width') && ~$img.attr('width').indexOf('%')) {
      flag = true;
    }
    return flag;
  }
  return {
    qtiClass: 'simpleChoice.choiceInteraction',
    getContainer: getContainer,
    template: tpl,
    getData: function getData(choice, data) {
      data.unique = parseInt(data.interaction.attributes.maxChoices) === 1;
      return data;
    },
    render: function render(simpleChoice) {
      var $container = getContainer(simpleChoice);
      if (hasRelativeSizedImage($container)) {
        var imgSrc = $container.find('img').attr('src');
        var $label = $container.find('label');
        var $qtiBlock = $container.find('.qti-block');
        $label.attr('data-has-relative-image', 'true');
        $qtiBlock.css('background-image', "url(".concat(imgSrc, ")"));
      }
    }
  };
});
