define('taoQtiPrint/qtiPrintRenderer/renderers/RubricBlock',['tpl!taoQtiPrint/qtiPrintRenderer/tpl/rubricBlock', 'taoQtiPrint/qtiPrintRenderer/helpers/container'], function (tpl, getContainer) {
  'use strict';
  return {
    qtiClass: 'rubricBlock',
    getContainer: getContainer,
    template: tpl,
    getData: function getData(rubric, data) {
      if (rubric.isEmpty()) {
        data.empty = true;
      }
      return data;
    }
  };
});
