define('taoQtiPrint/qtiPrintRenderer/renderers/Figure',['tpl!taoQtiPrint/qtiPrintRenderer/tpl/figure', 'taoQtiPrint/qtiPrintRenderer/helpers/container'], function (tpl, getContainer) {
  'use strict';

  return {
    qtiClass: 'figure',
    getContainer: getContainer,
    template: tpl,
    render: function render(figure) {
      var $figure = getContainer(figure);
      var $img = $figure.find('img');
      if ($img.length) {
        $figure.css({
          width: $img.attr('width')
        });
        $img.attr('width', '100%');
      }
    }
  };
});
